// Auto-generated embedded base64 fonts for high-fidelity offline image exports

export const amiri700Base64 = "";

export const amiri400Base64 = "";

export const scheherazade700Base64 = "";

export const scheherazade400Base64 = "";

export const lateef700Base64 = "";

export const lateef400Base64 = "";

export function getEmbeddedFontCSS(fontName: string): string {
  if (fontName === 'Scheherazade New') {
    return `
      @font-face {
        font-family: 'Scheherazade New';
        font-weight: 400;
        font-style: normal;
        src: url('data:font/woff2;base64,${scheherazade400Base64}') format('woff2');
      }
      @font-face {
        font-family: 'Scheherazade New';
        font-weight: 700;
        font-style: normal;
        src: url('data:font/woff2;base64,${scheherazade700Base64}') format('woff2');
      }
    `;
  }
  if (fontName === 'Lateef') {
    return `
      @font-face {
        font-family: 'Lateef';
        font-weight: 400;
        font-style: normal;
        src: url('data:font/woff2;base64,${lateef400Base64}') format('woff2');
      }
      @font-face {
        font-family: 'Lateef';
        font-weight: 700;
        font-style: normal;
        src: url('data:font/woff2;base64,${lateef700Base64}') format('woff2');
      }
    `;
  }
  // Default: Amiri
  return `
    @font-face {
      font-family: 'Amiri';
      font-weight: 400;
      font-style: normal;
      src: url('data:font/woff2;base64,${amiri400Base64}') format('woff2');
    }
    @font-face {
      font-family: 'Amiri';
      font-weight: 700;
      font-style: normal;
      src: url('data:font/woff2;base64,${amiri700Base64}') format('woff2');
    }
  `;
}
